//! Unicode 17 property delta over the pinned ICU 2.0 tables.
//!
//! The workspace pins `icu_properties 2.0.2` (Unicode 16): the vendored
//! Boa oracle pins the whole ICU family at `~2.0`, so the resolver cannot
//! move the RegExp lane to ICU 2.3 (Unicode 17) without re-vendoring Boa.
//! This module carries the exact Unicode 16 -> 17 delta for property
//! values: newly added names resolve to full range sets, changed names
//! patch the ICU 2.0 ranges as `(base u add) - rem`, and anything absent
//! passes through untouched (identical across versions or invalid in both).
//!
//! Provenance: `icu_properties_data 2.0.1` vs `2.3.0` (Unicode 16 vs 17),
//! diffed per resolved value. Regenerating: `/tmp/genprops` (throwaway
//! crate, not committed) replicates `unicode_property_ranges` under each
//! ICU version and dumps JSON; `/tmp/emit_delta.py` diffs and emits this
//! file. Sibling spellings (`gc=`/`sc=`/`scx=`/bare) share their observed
//! key's delta. The consuming code-point property owner has already validated
//! the complete name and value; only its typed Unicode 17 Script value can
//! supply a missing ICU base, so invalid combinations remain unresolvable.

/// One row authority owns every new Script's exact aliases and pinned ranges.
macro_rules! unicode17_script_rows {
    ($($variant:ident => [$($alias:literal),+] => [$($range:expr),+]),+ $(,)?) => {
        #[derive(Clone, Copy)]
        pub(crate) enum Unicode17Script { $($variant),+ }
        impl Unicode17Script {
            pub(crate) const ALL: &'static [Self] = &[$(Self::$variant),+];
            pub(crate) fn from_alias(value: &str) -> Option<Self> {
                match value { $($($alias)|+ => Some(Self::$variant),)+ _ => None }
            }
            pub(crate) const fn aliases(self) -> &'static [&'static str] {
                match self { $(Self::$variant => &[$($alias),+]),+ }
            }
            pub(crate) const fn ranges(self) -> &'static [(u32, u32)] {
                match self { $(Self::$variant => &[$($range),+]),+ }
            }
        }
    };
}

unicode17_script_rows! {
    BeriaErfe => ["Beria_Erfe", "Berf"] => [(0x16ea0, 0x16eb8), (0x16ebb, 0x16ed3)],
    Sidetic => ["Sidetic", "Sidt"] => [(0x10940, 0x10959)],
    TaiYo => ["Tai_Yo", "Tayo"] => [(0x1e6c0, 0x1e6de), (0x1e6e0, 0x1e6f5), (0x1e6fe, 0x1e6ff)],
    TolongSiki => ["Tolong_Siki", "Tols"] => [(0x11db0, 0x11ddb), (0x11de0, 0x11de9)],
}

/// Names ICU 2.0 resolves that Unicode 17 removed (none currently).
fn unicode17_removed(value: &str) -> bool {
    let _ = value;
    false
}

