/// Bring an ICU 2.0 property resolution up to Unicode 17.
///
/// The consumed property owns exact ECMAScript name/value validation. A missing
/// base receives only that owner's typed new-Script ranges; arbitrary delta rows
/// cannot publish ranges for an invalid property.
pub(crate) fn apply_unicode17_delta(
    property: crate::regexp::RegExpCodePointProperty<'_>,
    base: Option<Vec<(u32, u32)>>,
) -> Option<Vec<(u32, u32)>> {
    let value = property.spelling();
    match base {
        None => property.new_script_ranges().map(|ranges| ranges.to_vec()),
        Some(ranges) => {
            if unicode17_removed(value) {
                return None;
            }
            let Some((add, rem)) = unicode17_delta(value) else {
                return Some(ranges);
            };
            let mut merged = ranges;
            merged.extend_from_slice(add);
            merged.sort();
            let mut united: Vec<(u32, u32)> = Vec::with_capacity(merged.len());
            for (start, end) in merged {
                if let Some(last) = united.last_mut() {
                    if start <= last.1.saturating_add(1) {
                        last.1 = last.1.max(end);
                        continue;
                    }
                }
                united.push((start, end));
            }
            if rem.is_empty() {
                return Some(united);
            }
            let mut out: Vec<(u32, u32)> = Vec::new();
            let mut j = 0;
            for (start, end) in united {
                let mut cursor = start;
                while j < rem.len() && rem[j].1 < cursor {
                    j += 1;
                }
                let mut k = j;
                while k < rem.len() && rem[k].0 <= end {
                    if rem[k].0 > cursor {
                        out.push((cursor, rem[k].0 - 1));
                    }
                    cursor = cursor.max(rem[k].1.saturating_add(1));
                    if cursor > end || rem[k].1 == u32::MAX {
                        break;
                    }
                    k += 1;
                }
                if cursor <= end {
                    out.push((cursor, end));
                }
            }
            Some(out)
        }
    }
}
